#define DMC_DRAM_WD14                              ((0x01ee  << 2) + 0xfe036000)
#define DMC_DRAM_WD15                              ((0x01ef  << 2) + 0xfe036000)
#define DMC_DRAM_RD0                               ((0x01f0  << 2) + 0xfe036000)
#define DMC_DRAM_RD1                               ((0x01f1  << 2) + 0xfe036000)
#define DMC_DRAM_RD2                               ((0x01f2  << 2) + 0xfe036000)
